// ── STEP 2 — NEW JOB PREFERENCES ─────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════════

function NewJobScreen({ onNav, uploadedFile }) {
  const [shops,       setShops]       = useState([]);
  const [shopId,      setShopId]      = useState('');
  const [colorMode,   setColorMode]   = useState('bw');
  const [paperSize,   setPaperSize]   = useState('A4');
  const [copies,      setCopies]      = useState(1);
  const [doubleSided, setDoubleSided] = useState(false);

  const [pagesMode,   setPagesMode]   = useState('all');
  const [customPages, setCustomPages] = useState('');

  const [amount,      setAmount]      = useState(0);
  const [loading,     setLoading]     = useState(false);
  const [err,         setErr]         = useState('');

  const fileName = uploadedFile?.name || 'document.pdf';

  // ✅ PARSER FUNCTION (NEW)
  const parsePages = (input) => {
    if (!input) return 0;

    let pages = new Set();
    const parts = input.split(',');

    for (let part of parts) {
      part = part.trim();

      if (part.includes('-')) {
        const [start, end] = part.split('-').map(n => parseInt(n));

        if (!start || !end || start > end) return null;

        for (let i = start; i <= end; i++) {
          pages.add(i);
        }
      } else {
        const num = parseInt(part);
        if (!num) return null;
        pages.add(num);
      }
    }

    return pages.size;
  };

  const parsedPages = pagesMode === 'custom' ? parsePages(customPages) : 1;
  const pages = parsedPages || 0;

  useEffect(() => {
    api.get('/shops/nearby/').then(r => setShops(r.data.shops || [])).catch(() => {});
  }, []);

  useEffect(() => {
    const RATES = { bw:{ A4:1.5, A3:2.25, Letter:1.5 }, color:{ A4:7, A3:10.5, Letter:7 } };
    const rate  = (RATES[colorMode] || RATES.bw)[paperSize] || 1.5;

    setAmount(+(rate * pages * copies * (doubleSided ? 0.8 : 1)).toFixed(2));
  }, [pages, colorMode, paperSize, copies, doubleSided]);

  const submit = async () => {
    if (!shopId) { setErr('Please select a shop'); return; }

    if (pagesMode === 'custom') {
      const parsed = parsePages(customPages);
      if (!parsed) {
        setErr('Enter valid pages (e.g. 1-3,5,8-10)');
        return;
      }
    }

    setLoading(true); setErr('');

    try {
      if (uploadedFile) {
        const fd = new FormData();
        fd.append('file', uploadedFile);
        fd.append('shop_id', shopId);
        fd.append('file_name', fileName);
        fd.append('pages', pages);

        // ✅ OPTIONAL: send raw page string (important for backend later)
        fd.append('page_ranges', customPages);

        fd.append('color_mode', colorMode);
        fd.append('paper_size', paperSize);
        fd.append('copies', copies);
        fd.append('double_sided', doubleSided);

        await api.post('/jobs/create/', fd, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
      } else {
        await api.post('/jobs/create/', {
          shop_id: shopId,
          file_name: fileName,
          pages,
          page_ranges: customPages,
          color_mode: colorMode,
          paper_size: paperSize,
          copies,
          double_sided: doubleSided
        });
      }

      onNav('jobs');

    } catch (e) {
      setErr(e.response?.data?.error || 'Failed to create job');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={css.page}>
      <BackBtn onClick={() => onNav('upload')}/>

      <div style={css.pageTitle}>Print preferences</div>

      <div style={css.col}>

        {/* Pages */}
        <div style={css.card}>
          <label style={css.label}>Pages</label>

          <div style={{ ...css.row, marginBottom:10 }}>
            <Chip val="all" cur={pagesMode} onSet={setPagesMode} label="📄 All pages"/>
            <Chip val="custom" cur={pagesMode} onSet={setPagesMode} label="✏️ Custom"/>
          </div>

          {pagesMode === 'all' && (
            <div style={{ fontSize:12, color:G.text3 }}>
              Entire document will be printed
            </div>
          )}

          {pagesMode === 'custom' && (
            <div>
              <input
                style={{ ...css.input, fontSize:16, fontWeight:600 }}
                placeholder="e.g. 1-3,5,8-10"
                value={customPages}
                onChange={e => setCustomPages(e.target.value)}
              />

              {parsedPages > 0 && (
                <div style={{ fontSize:12, color:'#4ADE80', marginTop:6 }}>
                  Printing {parsedPages} page{parsedPages > 1 ? 's' : ''}
                </div>
              )}
            </div>
          )}
        </div>

        {/* Cost */}
        <div style={{ background:G.greenBg, border:`1px solid ${G.greenBdr}`, borderRadius:14, padding:20, textAlign:'center' }}>
          <div style={{ fontSize:12, color:'#4ADE80' }}>Estimated total</div>
          <div style={{ fontSize:36, fontWeight:900, color:G.green }}>₹{amount}</div>
        </div>

        <Alert msg={err}/>

        <button
          style={{ ...css.btn, opacity: loading || !shopId ? 0.5 : 1 }}
          onClick={submit}
          disabled={loading || !shopId}>
          {loading ? 'Creating job…' : 'Create job →'}
        </button>

      </div>
    </div>
  );
}


// ── SHOPS ─────────────────────────────────────────────────────────────────────
function ShopsScreen() {
